#!/bin/sh
# Generated by FWShift: an AWS Network Firewall policy and its stateful rule group, created with the AWS CLI. Read the
# report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE    prints the calls, makes none (no AWS access needed)
#   CHECK=1 sh THIS_FILE      sends every call with --dry-run: AWS checks the requests and the permissions
#   sh THIS_FILE              creates the rule group and the policy
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The policy is attached to no firewall: nothing changes for any traffic until you associate it:
#   aws network-firewall associate-firewall-policy --firewall-name FIREWALL --firewall-policy-arn ARN
# A rule group or policy of the same name stops the script before anything is created; a call AWS refuses stops it
# where it is (delete what it made with aws network-firewall delete-rule-group / delete-firewall-policy and run it
# again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws network-firewall' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
TMP=$(mktemp -d) || fail "mktemp"
trap 'rm -rf "$TMP"' EXIT
# free_group NAME / free_policy NAME: stop the script when one of that name exists
free_group() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-rule-group --rule-group-name "$1" --type STATEFUL $AWS_OPTS >/dev/null 2>&1; then
    fail "a rule group named $1 exists already; nothing was created"
  fi
}
free_policy() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-firewall-policy --firewall-policy-name "$1" $AWS_OPTS >/dev/null 2>&1; then
    fail "a firewall policy named $1 exists already; nothing was created"
  fi
}
# group NAME CAPACITY FILE: creates a stateful rule group and prints its ARN
group() {
  if [ -n "$DRY_RUN" ]; then
    show create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3"
    printf 'arn:aws:network-firewall:dryrun:000000000000:stateful-rulegroup/%s\n' "$1"
    return 0
  fi
  if [ -n "$CHECK" ]; then
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --dry-run --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1 (dry run)"
    printf 'checked: rule group %s\n' "$1" >&2
  else
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --description 'Generated by FWShift' --tags Key=fwshift,Value=generated \
      --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1"
    printf 'created %s\n' "$arn" >&2
  fi
  printf '%s\n' "$arn"
}
# policy NAME FILE CHECKFILE: creates the firewall policy (with CHECK, checks it without its rule groups, which a dry run
# does not create)
policy() {
  if [ -n "$DRY_RUN" ]; then show create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2"; return 0; fi
  if [ -n "$CHECK" ]; then
    aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$3" --dry-run $AWS_OPTS >/dev/null \
      || fail "create-firewall-policy $1 (dry run)"
    printf 'checked: firewall policy %s\n' "$1" >&2
    return 0
  fi
  aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2" \
    --description 'Generated by FWShift; review the conversion report before associating it' \
    --tags Key=fwshift,Value=generated $AWS_OPTS >/dev/null || fail "create-firewall-policy $1"
  printf 'created firewall policy %s\n' "$1" >&2
}

# No rule group or policy of these names may exist.
free_group fwshift-rules
free_policy fwshift

# Rule group 1: 0 rules, in the order of the policy.
cat > "$TMP/group1.json" <<'FWSHIFT_JSON'
{
 "RulesSource": {
  "RulesString": "pass ip 0.0.0.0/32 any -> 0.0.0.0/32 any (msg:\"fwshift: no rules\"; flow:to_server; sid:1; rev:1;)\n"
 },
 "StatefulRuleOptions": {
  "RuleOrder": "STRICT_ORDER"
 }
}
FWSHIFT_JSON
G1=$(group fwshift-rules 100 "$TMP/group1.json") || exit 1

# The policy: every packet to the stateful engine, the rule groups in strict order, then the default of the source.
cat > "$TMP/policy.json" <<FWSHIFT_JSON
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"},"StatefulRuleGroupReferences":[{"ResourceArn":"${G1}","Priority":100}]}
FWSHIFT_JSON
cat > "$TMP/policy-check.json" <<'FWSHIFT_JSON'
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"}}
FWSHIFT_JSON
policy fwshift "$TMP/policy.json" "$TMP/policy-check.json"

# Not written:
#   LAN to Internet - internet.http: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   LAN to Internet - internet.https: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   LAN to Internet - standard.dns: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   LAN to Internet - standard.ping: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   Internet to Webserver - internet.https: the source of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network
#   Admin-PCs to Servers - standard.ssh: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network
#   Admin-PCs to Servers - remote.rdp: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network
#   Servers to Admin-PCs - remote.rdp: the source of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network; the destination of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network
#   Jump-Hosts to OT-Cell - Modbus-TCP (eth1 to eth3): the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth3, and a rule of Network Firewall names no zone: give the networks behind eth3 with --zone-network
#   Jump-Hosts to OT-Cell - Modbus-TCP (eth3 to eth3): the source of the rule is in zone eth3, and a rule of Network Firewall names no zone: give the networks behind eth3 with --zone-network; the destination of the rule is in zone eth3, and a rule of Network Firewall names no zone: give the networks behind eth3 with --zone-network
#   HMI to OT-Cell - OPC-UA: schedule 'Mon 06:00:00 - Mon 22:00:00; Tue 06:00:00 - Tue 22:00:00; Wed 06:00:00 - Wed 22:00:00; Thu 06:00:00 - Thu 22:00:00; Fri 06:00:00 - Fri 22:00:00' is not converted; the rule would apply at all times; the source of the rule is in zone eth3, and a rule of Network Firewall names no zone: give t
#   OT-Cell to HMI - OPC-UA: schedule 'Mon 06:00:00 - Mon 22:00:00; Tue 06:00:00 - Tue 22:00:00; Wed 06:00:00 - Wed 22:00:00; Thu 06:00:00 - Thu 22:00:00; Fri 06:00:00 - Fri 22:00:00' is not converted; the rule would apply at all times; the source of the rule is in zone eth3, and a rule of Network Firewall names no zone: give t
#   Monitoring to OT-Cell - standard.ping: disabled in the source
#   LAN to Mailserver - internet.smtp: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network
#   Branch Sites to LAN - remote.rdp: not converted: 'Branch Sites' is a VPN object, which is not converted; the destination of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network
#   LAN to Lab-v6 - internet.http: not converted: desktop object 'Lab-v6' cannot be read: attribute 'ipv6', which this parser does not read; the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network
#   DMZ to Internet - GRE-Tunnel: the source of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   DMZ to Internet - Legacy-App: not converted: service 'Legacy-App' cannot be read: an entry with 'sourceport', which this parser does not read; references 'Legacy-App': an entry with 'sourceport', which this parser does not read; the source of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networ
#   DMZ to Internet - standard.ssh: not converted: action 'drop', which is not a direction (LANCOM documents no rule that blocks); the source of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network; the destination of the rule is in zone WAN, and a rule of Network Fi
#   Internet to ? - internet.https: not converted: desktop object '0e5f1a2b-0000-4000-8000-000000000999' is not in the input; the source of the rule is in zone WAN, and a rule of Network Firewall names no zone: give the networks behind WAN with --zone-network
#   LAN to DMZ - Web: the source of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network; the destination of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network
#   DMZ to LAN - Web: the source of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network; the destination of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network
#   DMZ to LAN - vpn.ipsec: the source of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network; the destination of the rule is in zone eth1, and a rule of Network Firewall names no zone: give the networks behind eth1 with --zone-network
#   Printer to DMZ - internet.http: not converted: desktop object 'Printer' cannot be read: a host that names no interface; the destination of the rule is in zone eth2, and a rule of Network Firewall names no zone: give the networks behind eth2 with --zone-network

echo 'Done. Associate the policy with a firewall when you are ready; until then nothing changes.' >&2
